DROP VIEW IF EXISTS `ic_stock_transaction_history_view`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `ic_stock_transaction_history_view` AS select `pir`.`created_at` AS `date_time`,`p`.`id` AS `product_id`,`w`.`id` AS `warehouse_id`,`p`.`name` AS `product`,`p`.`sku` AS `sku`,`w`.`name` AS `warehouse`,concat(`s`.`first_name`,' ',`s`.`last_name`) AS `employee_source`,'Inbound' AS `type`,`pir`.`quantity` AS `quantity`,`pr`.`purchase_number` AS `reference`,`prcv`.`id` AS `document_id`,NULL AS `stock_after`,'Invoice import' AS `comments` from (((((`ic_purchase_item_receives` `pir` join `ic_products` `p` on((`pir`.`product_id` = `p`.`id`))) join `ic_purchase_receives` `prcv` on((`pir`.`purchase_receive_id` = `prcv`.`id`))) join `ic_purchases` `pr` on((`pr`.`id` = `prcv`.`purchase_id`))) join `ic_warehouses` `w` on((`pr`.`warehouse_id` = `w`.`id`))) left join `ic_suppliers` `s` on((`pr`.`supplier_id` = `s`.`id`))) union all select `ii`.`created_at` AS `date_time`,`p`.`id` AS `product_id`,`w`.`id` AS `warehouse_id`,`p`.`name` AS `product`,`p`.`sku` AS `sku`,`w`.`name` AS `warehouse`,concat(`c`.`first_name`,' ',`c`.`last_name`) AS `employee_source`,'Withdrawal' AS `type`,-(`ii`.`quantity`) AS `quantity`,`i`.`id` AS `reference`,`i`.`id` AS `document_id`,NULL AS `stock_after`,'Withdrawn' AS `comments` from ((((`ic_invoice_items` `ii` join `ic_invoices` `i` on((`i`.`id` = `ii`.`invoice_id`))) join `ic_products` `p` on((`ii`.`product_id` = `p`.`id`))) left join `ic_customers` `c` on((`i`.`customer_id` = `c`.`id`))) join `ic_warehouses` `w` on((`w`.`id` = (select `ic_purchases`.`warehouse_id` from `ic_purchases` where (`ic_purchases`.`created_by` = `i`.`created_by`) limit 1)))) where (`i`.`is_withdrawal` = 1);

SET FOREIGN_KEY_CHECKS=1;
